create table if not exists caption_templates (
  id text primary key,
  name text not null,
  category text not null check (category in ('classic', 'transition', 'animation')),
  description text not null,
  badge text,
  settings jsonb not null,
  word_patterns jsonb,
  preview_sample jsonb not null,
  display_order int default 0,
  is_public boolean default true,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null
);

alter table caption_templates enable row level security;

drop policy if exists "allow public read access" on caption_templates;
create policy "allow public read access"
  on caption_templates for select
  using (is_public = true);

insert into caption_templates (id, name, category, description, badge, display_order, settings, word_patterns, preview_sample)
